/**
 * The catalog model shared by the data pipeline (`sync`), the bundler
 * (`build`) and the checker (`validate`).
 *
 * Two committed inputs describe the index:
 *   - `data/snapshot.json` — facts read from the upstream awesome list, plus
 *     provenance. Regenerated by `npm run sync`; never hand-edited.
 *   - `data/curation.json` — the editorial layer: inclusion, theme, three-axis
 *     scores, verdicts. Hand-edited through pull requests.
 *
 * `mergeCatalog()` joins them and derives every score, so the number shown in
 * the UI is always reproducible from published factors and weights.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..')

export const THEMES = ['pet', 'game', 'meme', 'market', 'media', 'growth', 'other']

/** Weights are part of the published rubric; changing them is an editorial decision. */
export const WEIGHTS = { absurdity: 0.5, emotion: 0.3, craft: 0.2 }

/** Factor name -> curation field name, in the order the UI shows them. */
export const AXES = ['absurdity', 'emotion', 'craft']

export function computeScore(factors) {
  const value = AXES.reduce((sum, axis) => sum + (factors[axis] || 0) * WEIGHTS[axis], 0)
  return Math.round(value)
}

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'))
}

export function snapshotPath(root = ROOT) {
  return path.join(root, 'data', 'snapshot.json')
}

export function curationPath(root = ROOT) {
  return path.join(root, 'data', 'curation.json')
}

export function readSnapshot(root = ROOT) {
  return readJson(snapshotPath(root))
}

export function readCuration(root = ROOT) {
  return readJson(curationPath(root))
}

/**
 * Join the facts with the editorial layer.
 * @returns {{ errors: string[], catalog: object | null }}
 */
export function mergeCatalog(snapshot, curation) {
  const errors = []
  if (!snapshot || !Array.isArray(snapshot.entries)) errors.push('snapshot: entries[] is missing')
  if (!curation || typeof curation.entries !== 'object' || curation.entries === null) {
    errors.push('curation: entries{} is missing')
  }
  if (errors.length > 0) return { errors, catalog: null }

  const snapshotSlugs = new Set()
  for (const entry of snapshot.entries) {
    if (!entry || typeof entry.slug !== 'string' || entry.slug === '') {
      errors.push('snapshot: an entry has no slug')
      continue
    }
    if (snapshotSlugs.has(entry.slug)) errors.push(`snapshot: duplicate slug ${entry.slug}`)
    snapshotSlugs.add(entry.slug)
  }

  const entries = []
  const seen = new Set()
  for (const entry of snapshot.entries) {
    const decision = curation.entries[entry.slug]
    if (decision === undefined) {
      errors.push(`curation: missing decision for ${entry.slug}`)
      continue
    }
    seen.add(entry.slug)

    const merged = {
      slug: entry.slug,
      name: entry.name,
      owner: entry.owner,
      repo: entry.repo,
      repoPath: entry.repoPath ?? null,
      npm: entry.npm ?? null,
      stars: typeof entry.stars === 'number' ? entry.stars : null,
      addedAt: entry.addedAt ?? null,
      description: entry.description,
      include: decision.include === true,
      adult: decision.adult === true,
    }

    if (merged.include) {
      merged.theme = decision.theme
      merged.absurdity = decision.absurdity
      merged.emotion = decision.emotion
      merged.craft = decision.craft
      merged.score = computeScore(decision)
      merged.verdict = decision.verdict
    } else {
      merged.reason = decision.reason
      merged.score = null
    }
    entries.push(merged)
  }

  for (const slug of Object.keys(curation.entries)) {
    if (!snapshotSlugs.has(slug)) errors.push(`curation: unknown slug ${slug} (not in snapshot)`)
  }

  const included = entries.filter((entry) => entry.include)
  included.sort((a, b) => b.score - a.score || a.slug.localeCompare(b.slug))
  const excluded = entries.filter((entry) => !entry.include)
  excluded.sort((a, b) => a.slug.localeCompare(b.slug))

  const catalog = {
    generatedAt: snapshot.generatedAt,
    upstream: snapshot.upstream,
    rubric: {
      weights: WEIGHTS,
      scale: curation.rubric?.scale ?? '0-100 integers',
      formula: 'score = round(absurdity×0.5 + emotion×0.3 + craft×0.2)',
    },
    counts: {
      audited: entries.length,
      included: included.length,
      excluded: excluded.length,
    },
    entries: included.concat(excluded),
  }

  return { errors, catalog }
}

/** Load both inputs and merge them; throws when the merge is inconsistent. */
export function loadCatalog(root = ROOT) {
  const { errors, catalog } = mergeCatalog(readSnapshot(root), readCuration(root))
  if (errors.length > 0) {
    throw new Error(`catalog data is inconsistent:\n- ${errors.join('\n- ')}`)
  }
  return catalog
}
